const buildTopics = (category, topicsByLevel, describe) =>
  Object.entries(topicsByLevel).flatMap(([level, titles]) =>
    titles.map((title) => ({ title, category, level, description: describe(title) }))
  );

const vocabularyTopics = buildTopics(
  'vocabulary',
  VOCAB_TOPICS_BY_LEVEL,
  (title) => `${title} temalı temel kelime seti.`
);
const writingTopics = Object.entries(WRITING_DATA).flatMap(([level, items]) =>
  items.map(({ title, passage, instructions }) => ({
    title,
    category: 'writing',
    level,
    description: instructions,
    passage,
  }))
);
const readingTopics = Object.entries(READING_DATA).flatMap(([level, items]) =>
  items.map(({ title, passage }) => ({
    title,
    category: 'reading',
    level,
    description: `${title} başlıklı okuma parçası ve anlama soruları.`,
    passage,
  }))
);

